-- 01_schema.sql : tables, primary keys, foreign keys, constraints
-- Runs automatically on first start (files in ./sql run in filename order).
-- IDs use GENERATED BY DEFAULT so the data generator can load explicit IDs with COPY.
-- After a bulk load that supplies IDs, reset the sequences (see the Phase 3 loader).

CREATE TABLE security (
    ticker        VARCHAR(20)   PRIMARY KEY,
    company_name  VARCHAR(100)  NOT NULL,
    sector        VARCHAR(50)   NOT NULL,
    exchange      VARCHAR(20)   NOT NULL,
    tick_size     NUMERIC(10,4) NOT NULL CHECK (tick_size > 0),
    prev_close    NUMERIC(14,4) NOT NULL CHECK (prev_close > 0)
);

CREATE TABLE strategy (
    strategy_id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name              VARCHAR(80)   NOT NULL UNIQUE,
    strategy_type     VARCHAR(30)   NOT NULL
                      CHECK (strategy_type IN ('MOMENTUM','MEAN_REVERSION','MARKET_MAKING','ARBITRAGE','STAT_ARB')),
    assigned_capital  NUMERIC(18,2) NOT NULL CHECK (assigned_capital > 0)
);

CREATE TABLE app_user (
    user_id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username       VARCHAR(50)  NOT NULL UNIQUE,
    password_hash  VARCHAR(255) NOT NULL,
    role           VARCHAR(12)  NOT NULL CHECK (role IN ('TRADER','COMPLIANCE')),
    strategy_id    INTEGER      REFERENCES strategy (strategy_id),
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- a trader must be tied to a strategy; compliance users may be unassigned
    CONSTRAINT ck_trader_has_strategy
        CHECK (role <> 'TRADER' OR strategy_id IS NOT NULL)
);

CREATE TABLE market_quote (
    quote_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ticker      VARCHAR(20)   NOT NULL REFERENCES security (ticker),
    quote_ts    TIMESTAMPTZ   NOT NULL,
    bid_price   NUMERIC(14,4) NOT NULL CHECK (bid_price > 0),
    bid_qty     INTEGER       NOT NULL CHECK (bid_qty >= 0),
    ask_price   NUMERIC(14,4) NOT NULL CHECK (ask_price > 0),
    ask_qty     INTEGER       NOT NULL CHECK (ask_qty >= 0),
    last_price  NUMERIC(14,4) NOT NULL CHECK (last_price > 0),
    CONSTRAINT ck_quote_bid_le_ask CHECK (bid_price <= ask_price)
    -- uniqueness of (ticker, quote_ts) is enforced by a unique index in 02_indexes.sql
);

CREATE TABLE orders (
    order_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    strategy_id   INTEGER       NOT NULL REFERENCES strategy (strategy_id),
    ticker        VARCHAR(20)   NOT NULL REFERENCES security (ticker),
    side          VARCHAR(4)    NOT NULL CHECK (side IN ('BUY','SELL')),
    order_type    VARCHAR(6)    NOT NULL CHECK (order_type IN ('MARKET','LIMIT')),
    quantity      INTEGER       NOT NULL CHECK (quantity > 0),
    limit_price   NUMERIC(14,4),
    submitted_ts  TIMESTAMPTZ   NOT NULL,
    status        VARCHAR(10)   NOT NULL DEFAULT 'OPEN'
                  CHECK (status IN ('OPEN','PARTIAL','FILLED','CANCELLED')),
    CONSTRAINT ck_limit_price_rule CHECK (
        (order_type = 'LIMIT'  AND limit_price IS NOT NULL AND limit_price > 0) OR
        (order_type = 'MARKET' AND limit_price IS NULL)
    )
);

CREATE TABLE order_event (
    event_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id    BIGINT       NOT NULL REFERENCES orders (order_id) ON DELETE CASCADE,
    event_type  VARCHAR(12)  NOT NULL CHECK (event_type IN ('SUBMITTED','CANCELLED')),
    event_ts    TIMESTAMPTZ  NOT NULL,
    -- an order is submitted once and cancelled at most once
    CONSTRAINT uq_order_event UNIQUE (order_id, event_type)
);

CREATE TABLE execution (
    execution_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id      BIGINT        NOT NULL REFERENCES orders (order_id),   -- RESTRICT: fills are never silently deleted
    exec_qty      INTEGER       NOT NULL CHECK (exec_qty > 0),
    exec_price    NUMERIC(14,4) NOT NULL CHECK (exec_price > 0),
    exec_ts       TIMESTAMPTZ   NOT NULL
);

-- End-of-day snapshot per strategy, ticker and trade date.
-- quantity is signed (negative = short); realised_pnl is the realised P&L generated on that date.
CREATE TABLE position (
    strategy_id      INTEGER       NOT NULL REFERENCES strategy (strategy_id),
    ticker           VARCHAR(20)   NOT NULL REFERENCES security (ticker),
    trade_date       DATE          NOT NULL,
    quantity         INTEGER       NOT NULL,
    avg_entry_price  NUMERIC(14,4) CHECK (avg_entry_price IS NULL OR avg_entry_price > 0),
    realised_pnl     NUMERIC(18,4) NOT NULL DEFAULT 0,
    PRIMARY KEY (strategy_id, ticker, trade_date)
);

CREATE TABLE risk_metric (
    strategy_id         INTEGER       NOT NULL REFERENCES strategy (strategy_id),
    trade_date          DATE          NOT NULL,
    gross_exposure      NUMERIC(18,2) NOT NULL CHECK (gross_exposure >= 0),
    net_exposure        NUMERIC(18,2) NOT NULL,
    daily_pnl           NUMERIC(18,2) NOT NULL,
    max_position_value  NUMERIC(18,2) NOT NULL CHECK (max_position_value >= 0),
    available_capital   NUMERIC(18,2) NOT NULL,
    PRIMARY KEY (strategy_id, trade_date)
);

CREATE TABLE surveillance_config (
    param_name   VARCHAR(50)   PRIMARY KEY,
    param_value  NUMERIC(12,4) NOT NULL,
    description  VARCHAR(200)
);